:root,
:host {
	--ck-find-and-replace-form-width: var(--ck-width-dialog);
	--ck-find-and-replace-form-replace-field-padding-top: var(--ck-spacing-padding-comfortable);
	/* Defaults to the shared actions padding; the inputs area can be tuned independently. */
	--ck-find-and-replace-form-inputs-padding: var(--ck-spacing-padding-spacious) var(--ck-spacing-padding-comfortable) var(--ck-spacing-padding-compact) var(--ck-spacing-padding-comfortable);
	/* No top padding — the inputs' bottom padding already provides the gap between the two sections. */
	--ck-find-and-replace-form-actions-padding: 0 var(--ck-spacing-padding-comfortable) var(--ck-spacing-padding-comfortable) var(--ck-spacing-padding-comfortable);
	/* The font size of the results counter. Declared `initial` and read on the counter with the field font size as
	   fallback, so the counter follows the field text, also when the field font size is overridden on the form. */
	--ck-find-and-replace-form-results-counter-font-size: initial;
	/* The text color of the results counter. Declared `initial` and read on the counter with the foundation color as
	   fallback (no text role has this value), so the counter follows the foundation color also when it is overridden
	   on the form. */
	--ck-find-and-replace-form-results-counter-text-color: initial;
}

.ck.ck-find-and-replace-form {
	width: var(--ck-find-and-replace-form-width);
	max-width: 100%;

	/*
	 * The <form> needs tabindex="-1" for proper Esc handling after being clicked
	 * but the side effect is that this creates a nasty focus outline in some browsers.
	 */
	&:focus {
		outline: none;
	}

	/* Generic styles for the form inputs and actions. */
	& .ck-find-and-replace-form__inputs,
	& .ck-find-and-replace-form__actions {
		display: flex;
		flex: 1 1 auto;
		flex-direction: row;
		flex-wrap: wrap;
		align-items: center;
		align-content: stretch;

		padding: var(--ck-dialog-actions-padding);
		margin: 0;

		& > .ck-button {
			flex: 0 0 auto;
		}

		[dir="ltr"] & {
			& > * + * {
				margin-left: var(--ck-spacing-standard, var(--ck-spacing-base));
			}
		}

		[dir="rtl"] & {
			& > * + * {
				margin-right: var(--ck-spacing-standard, var(--ck-spacing-base));
			}
		}

		& .ck-labeled-field-view {
			flex: 1 1 auto;

			& .ck-input {
				width: 100%;
				min-width: 50px;
			}
		}

	}

	/* Styles specific for inputs area. */
	& .ck-find-and-replace-form__inputs {
		padding: var(--ck-find-and-replace-form-inputs-padding);

		/* To display all controls in line when there's an error under the input */
		align-items: flex-start;

		& > .ck-button-prev > .ck-icon {
			transform: rotate(90deg);
		}

		& > .ck-button-next > .ck-icon {
			transform: rotate(-90deg);
		}

		& .ck-results-counter {
			position: absolute;
			top: 50%;
			transform: translateY(-50%);

			color: var(--ck-find-and-replace-form-results-counter-text-color, var(--ck-color-base-border));
			font-size: var(--ck-find-and-replace-form-results-counter-font-size, var(--ck-input-font-size));

			[dir="ltr"] & {
				right: var(--ck-spacing-standard, var(--ck-spacing-base));
			}

			[dir="rtl"] & {
				left: var(--ck-spacing-standard, var(--ck-spacing-base));
			}
		}

		& > .ck-labeled-field-replace {
			flex: 0 0 100%;
			padding-top: var(--ck-find-and-replace-form-replace-field-padding-top);

			[dir="ltr"] & {
				margin-left: 0;
			}

			[dir="rtl"] & {
				margin-right: 0;
			}
		}
	}

	/* Styles specific for actions area. */
	& .ck-find-and-replace-form__actions {
		padding: var(--ck-find-and-replace-form-actions-padding);
		flex-wrap: wrap;
		justify-content: flex-end;
	}

	& .ck-switchbutton {
		width: 100%;
		display: flex;
		flex-direction: row;
		flex-wrap: nowrap;
		justify-content: space-between;
		align-items: center;
	}
}

@media screen and (max-width: 600px) {
	.ck.ck-find-and-replace-form {
		width: 300px;

		/* Don't let the form overflow from the dialog (https://github.com/ckeditor/ckeditor5-commercial/issues/5913) */
		max-width: 100%;

		/* Don't let the "Find" field push the prev/next buttons to the next line. */
		& .ck-find-and-replace-form__inputs > .ck-labeled-field-view:not(.ck-labeled-field-replace) {
			flex: 1 1 0;
			min-width: 0;
		}

		/* "Replace all" and "Replace" share the first row, "Find" takes the full row below. */
		& .ck-find-and-replace-form__actions > .ck-button {
			flex: 1 1 0;
			min-width: 0;
			justify-content: center;
		}

		& .ck-find-and-replace-form__actions > .ck-button-find {
			flex: 0 0 100%;
			margin-top: var(--ck-spacing-standard, var(--ck-spacing-base));

			[dir="ltr"] & {
				margin-left: 0;
			}

			[dir="rtl"] & {
				margin-right: 0;
			}
		}

		/* Styles specific for inputs area. */
		&.ck-find-and-replace-form__input {
			flex-wrap: wrap;

			& .ck-labeled-field-view {
				flex: 1 0 auto;
				width: 100%;
				margin-bottom: var(--ck-spacing-standard, var(--ck-spacing-base));
			}

			& > .ck-button {
				text-align: center;

				&:first-of-type {
					flex: 1 1 auto;

					[dir="ltr"] & {
						margin-left: 0;
					}

					[dir="rtl"] & {
						margin-right: 0;
					}

					& .ck-button__label {
						width: 100%;
						text-align: center;
					}
				}
			}
		}

		/* Styles specific for actions area. */
		&.ck-find-and-replace-form__actions > :not(.ck-labeled-field-view) {
			flex-wrap: wrap;
			flex: 1 1 auto;

			& > .ck-button {
				text-align: center;

				&:first-of-type {
					flex: 1 1 auto;

					[dir="ltr"] & {
						margin-left: 0;
					}

					[dir="rtl"] & {
						margin-right: 0;
					}
				}

				& .ck-button__label {
					width: 100%;
					text-align: center;
				}
			}
		}
	}
}
