:root,
:host {
	/**
	 * The spread radius of the focus shadow.
	 */
	--ck-focus-shadow-spread: 3px;

	/**
	 * The geometry of the focus shadow.
	 */
	--ck-focus-shadow-geometry: 0 0 0 var(--ck-focus-shadow-spread);

	/**
	 * A visual style of focused element's shadow.
	 */
	/* Backward compatibility: falls back to legacy --ck-focus-outer-shadow-geometry if overridden. */
	--ck-focus-shadow: var(--ck-focus-outer-shadow-geometry, var(--ck-focus-shadow-geometry)) var(--ck-color-focus-outer-shadow);

	/**
	 * A visual style of focused element's shadow (when disabled).
	 */
	/* Backward compatibility: falls back to legacy --ck-focus-outer-shadow-geometry if overridden. */
	--ck-focus-shadow-disabled: var(--ck-focus-outer-shadow-geometry, var(--ck-focus-shadow-geometry)) var(--ck-color-focus-disabled-shadow);

	/**
	 * A visual style of focused element's shadow (when has errors).
	 */
	/* Backward compatibility: falls back to legacy --ck-focus-outer-shadow-geometry if overridden. */
	--ck-focus-shadow-error: var(--ck-focus-outer-shadow-geometry, var(--ck-focus-shadow-geometry)) var(--ck-color-focus-error-shadow);

	/**
	 * A visual style of focused element's border or outline.
	 */
	--ck-focus-ring: 1px solid var(--ck-color-focus-border);

	/**
	 * The border color applied to focused elements.
	 * Use this instead of --ck-focus-ring when the component has a customizable border-width,
	 * to avoid overriding the width on focus.
	 */
	--ck-focus-border-color: var(--ck-color-base-focus);

	/**
	 * Contrast outline for fake collapsed selections and carets.
	 * Used across link, widget, emoji, and bookmark packages.
	 */
	--ck-outline-fake-caret: solid 1px hsl(0 0% 100% / .5);
}
